-- =====================================================================
-- Strive Elite - the Dribbling Transformation course, rebuilt in the app
-- =====================================================================
-- Coach Yinka, Nov 5 2026: "I want you to rebuild it and host on your OWN
-- domain." The course had been a separate static site (a zip, also
-- served by the app behind the login as 058/059 pages). It is now a
-- native course on the Courses tab: a LESSON course of 27 pages in six
-- parts, every drill a page with its video, its specs line and its
-- setup, execution and key cues, the Phase 1 to 3 overviews, the
-- 60-minute session, the 30-day plan and the mindset pages. Words are the
-- course's own; the only change is that em dashes became colons, commas
-- and full stops (the house rule). The drill videos are the same files
-- the drill bank already uses (Manus-hosted), so they play the same way.
-- NOT carried over: the hero video (a file not in the repo) and the two
-- quote photos (lesson pages have no image field).
--
-- The course row held a link course (058/059); it becomes a lesson
-- course, loses its address, and stays ON. Idempotent: runs only while the
-- course has no steps; refuses a partial.
-- =====================================================================

do $$
declare
  cid uuid;
  placed int;
begin
  select id into cid from public.elite_courses where slug = 'dribbling-transformation';
  if cid is null then
    insert into public.elite_courses (slug, name, subtitle, intro, kind, active, sort)
    values ('dribbling-transformation', 'Dribbling Transformation', 'Most dangerous dribbler on the team.', E'60 minutes of structured training.\nTrain 5 days a week, minimum.\nConsistency beats intensity every time.', 'lesson', true, 15)
    returning id into cid;
  elsif exists (select 1 from public.elite_course_steps where course_id = cid) then
    return;
  else
    update public.elite_courses
       set kind = 'lesson', external_url = null, intro = E'60 minutes of structured training.\nTrain 5 days a week, minimum.\nConsistency beats intensity every time.'
     where id = cid;
  end if;
  insert into public.elite_course_steps (course_id, level_no, level_name, title, body, cue, video_url, sort) values
    (cid, 1, E'Start here', E'Welcome', E'A premium training system.\n\nThe course that turns raw potential into elite control. 60 minutes of structured daily training designed to make the ball do exactly what you want, every time.', null, null, 10),
    (cid, 1, E'Start here', E'The philosophy', E'Elite ball control is not a talent. It is a skill, and every skill is built through deliberate, structured repetition. The players you watch on screen who make dribbling look effortless did not get there by accident.\n\nThey trained the same moves hundreds of times until their feet stopped thinking and started reacting. That is what this course builds: automatic, confident, game-ready ball mastery.\n\n"Train it until you can''t get it wrong."\n\nEvery drill in this system is chosen because it transfers directly to real match situations. No gimmicks. No filler. Just the movements that make defenders freeze.', null, null, 20),
    (cid, 1, E'Start here', E'Session structure', E'0 to 15 min, Cone Weave: 3 drills. Inside & Outside, La Croqueta Cone Weave, 8-Cone Freestyle.\n\n15 to 25 min, Ball Mastery: 2 drills. Ronaldinho Drill, Figure 8 Dribbling.\n\n25 to 60 min, 1v1 Skills: 9 drills. Neymar Feint, Body Feint, Maradona, Mbappe Chop, La Croqueta, Reverse Elastico, Elastico, Stepover, Freestyle.\n\nTotal session: 60 minutes.', null, null, 30),
    (cid, 2, E'Phase 1: Cone Weave (0 to 15 min)', E'Phase 1: Cone Weave', E'0 to 15 minutes.\n\nEstablish your rhythm. Sharpen your touch. Prepare your feet for speed.\n\nIn this phase: Inside & Outside Cone Weave, La Croqueta Cone Weave, 8-Cone Freestyle.', null, null, 10),
    (cid, 2, E'Phase 1: Cone Weave (0 to 15 min)', E'Inside & Outside Cone Weave', E'Setup: 6-8 cones in a straight line, 1-3 feet apart.\n\nExecution: Weave through cones using inside and outside of ONE foot only. Switch feet on return.\n\nKey cues: Stay low. Quick touches. Head up when possible.', E'3 sets, 6 up and back (about 50 sec), max speed, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/vwzCCVyDFkTUIZfq.mp4', 20),
    (cid, 2, E'Phase 1: Cone Weave (0 to 15 min)', E'La Croqueta Cone Weave', E'Setup: 6-8 cones in a straight line, 1-3 feet apart.\n\nExecution: Push ball from inside of right foot to inside of left foot through each gap. Rhythm: "Inside-Inside-Forward".\n\nKey cues: Wide stance. Push, don''t kick. Smooth rhythm.', E'3 sets, 6 up and back (about 50 sec), max speed, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/POoQopaTzkWqvXpv.mov', 30),
    (cid, 2, E'Phase 1: Cone Weave (0 to 15 min)', E'8-Cone Inside & Outside', E'Setup: 6-8 cones in a straight line, 1-3 feet apart.\n\nExecution: Using ONE foot only, weave through cones using the inside and outside of the foot. Complete 2 sets on your right foot, then 2 sets on your left foot.\n\nKey cues: Stay low. Quick touches. Both feet, 2 sets each.', E'2 sets each foot, 6 up and back (about 50 sec), max speed, rest 60 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/QiblJbEqVTPozDud.mp4', 40),
    (cid, 3, E'Phase 2: Ball Mastery (15 to 25 min)', E'Phase 2: Ball Mastery', E'15 to 25 minutes.\n\nBuild your foundation. Develop the close control that separates good from elite.\n\nIn this phase: Ronaldinho Drill (1 min), Figure 8 Dribbling (3 x 1 min).', null, null, 10),
    (cid, 3, E'Phase 2: Ball Mastery (15 to 25 min)', E'Ronaldinho Drill', E'Setup: Stationary. Ball between feet.\n\nExecution: Controlled dribbling in a tight space. Focus on consistency and creativity with every touch.\n\nKey cues: Find a rhythm. Stay on toes. Have full control.', E'3 sets, 45 sec work, rhythmic, rest 30 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/sSDCRAmGquYZMddQ.mp4', 20),
    (cid, 3, E'Phase 2: Ball Mastery (15 to 25 min)', E'Figure 8 Dribbling', E'Setup: Two cones, 1-2 yards apart.\n\nExecution: Dribble in a Figure 8 pattern around both cones. Use inside and outside of both feet.\n\nKey cues: Small touches. Keep ball close. Sharp turns.', E'3 sets, 45 sec work, max control, rest 30 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/hTHXbVErXMeegCGE.mp4', 30),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Phase 3: 1v1 Skills', E'25 to 60 minutes.\n\nApply everything. Execute skill moves at full speed against imaginary defenders.\n\nIn this phase: Neymar Feint, Body Feint, Maradona Turn, Mbappe Chop, La Croqueta 1v1, Reverse Elastico, Elastico, Ronaldinho Step Over, Freestyle Dribbling.', null, null, 10),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Neymar Feint', E'Setup: Open space or a single cone as a defender.\n\nExecution: Dribble forward, stop abruptly, and drop your shoulder in the opposite direction. Explode forward past the defender.\n\nKey cues: Sell the fake. Drop shoulder. Explode out.', E'3 sets, 12 each side, explosive, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/oFUpYSVfdHkZMtUl.MP4', 20),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Body Feint', E'Setup: Open space or a single cone as a defender.\n\nExecution: Drop shoulder one way, push ball the other way. No step over, just body movement.\n\nKey cues: Low center of gravity. Big step to fake. Accelerate away.', E'3 sets, 12 each side, explosive, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/DwIDNpPWjIfESEPa.MP4', 30),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Maradona Turn', E'Setup: Single cone as a defender. Approach at pace.\n\nExecution: Drag ball with sole of one foot, spin 180° around the ball, drag again with the other foot to exit.\n\nKey cues: Shield with body. Tight spin. Accelerate out.', E'3 sets, 8 each side, controlled, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/rLwklYeePleghSHY.MP4', 40),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Mbappe Chop', E'Setup: Open space or a single cone as a defender.\n\nExecution: Fake shot or pass. Chop ball across body with inside of foot behind standing leg.\n\nKey cues: Fake the shot. Chop firmly. Explosive exit.', E'3 sets, 12 each side, high speed, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/NTNYbFKFgaMEpxiA.MP4', 50),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'La Croqueta 1v1', E'Setup: Open space or a single cone as a defender.\n\nExecution: Push ball across body from inside of one foot to inside of the other. Shift hips and accelerate past the defender.\n\nKey cues: One smooth push. Shift body weight. Explode after touch.', E'3 sets, 12 each side, explosive, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/cJyFfcoIukyYuKOl.MP4', 60),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Reverse Elastico', E'Setup: Open space or a single cone as a defender.\n\nExecution: Push the ball IN with the inside of your foot, then quickly snap it OUT with the outside of the same foot. "Inside-Outside."\n\nKey cues: Sell the outside touch. Quick snap back. Burst away.', E'3 sets, 12 each side, explosive, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/LUrnPLriXaIbxhDG.mp4', 70),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Elastico', E'Setup: Open space or a single cone as a defender.\n\nExecution: Push the ball OUT with the outside of your foot, then quickly snap it IN with the inside of the same foot. "Outside-Inside."\n\nKey cues: Push then snap. Use upper body. Change of pace.', E'3 sets, 12 each side, explosive, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/fSpCzUHlZbnqCRAW.mp4', 80),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Ronaldinho Step Over', E'Setup: Open space or a single cone as a defender.\n\nExecution: Touch the ball with the inside of your foot, scissor around it with the same foot, then push away with the outside of your opposite foot to escape.\n\nKey cues: Exaggerate step. Drop shoulder. Explode away.', E'3 sets, 12 each side, game speed, rest 45 sec.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/RfPrPewZZrnbhLyj.MP4', 90),
    (cid, 4, E'Phase 3: 1v1 Skills (25 to 60 min)', E'Freestyle Creative Dribbling', E'Setup: Open space. No cones. No structure.\n\nExecution: Combine all moves. Imagine defenders. Change pace. Change direction.\n\nKey cues: Be creative. Try new combos. Game speed.', E'The finisher. 2 sets, 1 min each, max creativity, rest 1 min.', E'https://files.manuscdn.com/user_upload_by_module/session_file/310519663373072550/isWTvYFmpepwbekU.mp4', 100),
    (cid, 5, E'The program', E'The 60-minute elite session', E'Warm up, 0 to 15 minutes: dynamic stretching, light jogging, juggling (feet only).\n\nCone weave, 15 to 25 minutes: Inside & Outside (4 sets), La Croqueta Weave (4 sets), 8-Cone Freestyle (4 sets).\n\nBall mastery, 25 to 40 minutes: Ronaldinho Drill (3 sets), Figure 8 (3 sets), Freestyle Box (3 sets).\n\n1v1 skills, 40 to 60 minutes: Neymar Feint (10 mins), Body Feint (10 mins), full speed execution.', null, null, 10),
    (cid, 5, E'The program', E'The 30-day training plan', E'Week 1, days 1 to 7: Foundation. Learn every drill at slow speed. Focus on correct technique. No rushing. Build the pattern.\n\nWeek 2, days 8 to 14: Repetition. Increase tempo. Run each drill at 70% speed. Start to feel the rhythm without thinking.\n\nWeek 3, days 15 to 21: Speed. Push to 90% speed. The moves should feel natural. Add explosive exits after each skill.\n\nWeek 4, days 22 to 30: Game Speed. Full match intensity. Combine moves. React, don''t think. This is where mastery is built.\n\nTrain 5 days per week minimum. Rest days are active recovery: light juggling or passing only. Consistency beats intensity every time.', null, null, 20),
    (cid, 6, E'Mindset', E'Comfort zone', E'When a drill feels awkward, that is not a sign you are doing it wrong. That is a sign you are doing it right. Discomfort means your brain is building something new.\n\nMost players stay comfortable. They practice what they are already good at. That is why most players plateau. Growth only happens at the edge of what you can currently do.\n\n"If it feels easy, you''re not growing."\n\nLean into the drills that feel hardest. The Elastico, the Maradona, the Reverse Elastico: these are the moves that will separate you. Stay with them longer than feels comfortable.', null, null, 10),
    (cid, 6, E'Mindset', E'Control', E'Ball mastery is not about tricks. It is about control: having the ball do exactly what you intend, every single time, under pressure, at speed.\n\nControl is what allows you to play simple when the game demands it, and complex when the moment calls for it. Without control, skill is just showboating. With it, you become dangerous.\n\n"Control the ball. Control the game." Andres Iniesta', null, null, 20),
    (cid, 6, E'Mindset', E'Talent and work', E'"Talent without working hard is nothing." Cristiano Ronaldo', null, null, 30),
    (cid, 6, E'Mindset', E'You have everything you need', E'The drills are in front of you. The programme is laid out. The only thing left is to show up: every day, every set, every rep.\n\nThe players who complete this course and come out the other side transformed are not the most talented. They are the most consistent. They are the ones who train when it is raining, when they are tired, when no one is watching.\n\nThat is the Strive standard. For the players. By the players. Now go train.', null, null, 40),
    (cid, 6, E'Mindset', E'Now train', E'You have the system. You have the drills. The only variable left is you.', null, null, 50);
  select count(*) into placed from public.elite_course_steps where course_id = cid;
  if placed <> 27 then
    raise exception 'Dribbling Transformation seed placed % of 27 pages', placed;
  end if;
end $$;
